 if(a==='freeze'){try{const decision=freezeDecision(state,{reason:$('#decisionReason').value,evidenceReviewed:$('#evidenceCheck').checked,assumptionsAccepted:$('#fxCheck').checked,pendingAccepted:!!$('#pendingCheck')?.checked});audit('Recommendation frozen',{version:state.version,rationale:decision.reason});decision.audit=structuredClone(state.audit);state.decision=decision;state.approved=true;save();render();}catch(e){notify(e.message);}return;}
