function buyerScopeLabel(scope){const selected=state.rfx.lines.filter(l=>(scope.lineIds||state.rfx.lines.map(l=>l.id)).includes(l.id));return selected.length+' requested items. '+(scope.qualityOnly===false?'Includes suppliers without mandatory qualification clearance for exploration. ':'Mandatory qualifications applied. ')+(scope.includeReview?'Includes unresolved readings for exploration. ':'Unresolved readings excluded. ')+(scope.excludedVendors?.length?'Excluded suppliers: '+scope.excludedVendors.join(', ')+'. ':'')+(Object.values(state.data).some(x=>x.quotes?.some(q=>q.currency==='USD'))?'Conversion: INR '+(scope.fx||state.rfx.fx)+' per USD.':'');}

function buyerError(message){if(/Model request failed|response_format|Invalid schema|schema.*invalid|not a function|sourceFile/i.test(message))return 'We could not process this AI request. Your saved work is still available.';if(/Live AI is off|Live AI is disabled/.test(message))return 'Connect AI before submitting a new requirement, extracting a response or asking a question.';return message;}
